/* lazy-export loader (inject classic script · shares scope · fallback + no double-load + no double-click) */
var _heavyExportP=null;
function _loadHeavyExport(){
  if(_heavyExportP)return _heavyExportP;
  _heavyExportP=new Promise(function(res,rej){
    var sc=document.createElement("script");sc.src="js/heavy-export.js?v=3.1.0";sc.async=true;
    sc.onload=function(){res();};
    sc.onerror=function(){_heavyExportP=null;rej(new Error("heavy-export.js load failed"));};
    document.head.appendChild(sc);
  });
  return _heavyExportP;
}
var _expInflight={};
function _expInvoke(name,args){
  if(_expInflight[name])return Promise.resolve();
  _expInflight[name]=true;
  return _loadHeavyExport().then(function(){
    var m=window.HeavyExport||{};
    if(typeof m[name]!=="function")throw new Error("no export fn: "+name);
    return m[name].apply(null,args);
  }).catch(function(e){
    console.error("[Export] "+name+" failed:",e);
    try{toast("ไม่สามารถโหลดระบบ Export ได้ กรุณาลองใหม่อีกครั้ง","error");}catch(_){try{alert("ไม่สามารถโหลดระบบ Export ได้ กรุณาลองใหม่อีกครั้ง");}catch(__){}}
  }).then(function(r){_expInflight[name]=false;return r;},function(e){_expInflight[name]=false;throw e;});
}
function openExportChooser(force){return _expInvoke("openExportChooser",[force]);}
function exportExcel(){return _expInvoke("exportExcel",[]);}
function docExportExcel(){return _expInvoke("docExportExcel",[]);}
function exportBackup(){return _expInvoke("exportBackup",[]);}
/* lazy-chunk loader (classic-script inject · cache/dedup · fallback · shared scope) */
var _chunkP={};
function _loadChunk(name){
  if(_chunkP[name])return _chunkP[name];
  _chunkP[name]=new Promise(function(res,rej){
    var sc=document.createElement("script");sc.src="js/heavy-"+name+".js?v=3.1.0";sc.async=true;
    sc.onload=function(){res();};
    sc.onerror=function(){_chunkP[name]=null;rej(new Error("chunk "+name+" load failed"));};
    document.head.appendChild(sc);
  });
  return _chunkP[name];
}
function _lazyCall(name,fn,args){
  return _loadChunk(name).then(function(){return window[fn].apply(null,args);})
    .catch(function(e){console.error("[lazy "+name+"] "+fn,e);try{toast("โหลดไม่สำเร็จ กรุณาลองใหม่อีกครั้ง","error");}catch(_){try{alert("โหลดไม่สำเร็จ กรุณาลองใหม่อีกครั้ง");}catch(__){}}});
}
function _lazyRender(name,fn,args){
  var host=document.getElementById("view-root");
  if(host)host.innerHTML='<div style="padding:48px;text-align:center;opacity:.65;font-size:15px">กำลังโหลด...</div>';
  return _loadChunk(name).then(function(){return window[fn].apply(null,args);})
    .catch(function(e){console.error("[lazy "+name+"] "+fn,e);if(host)host.innerHTML='<div style="padding:48px;text-align:center;color:#ef4444">โหลดหน้าไม่สำเร็จ กรุณาลองใหม่</div>';});
}
function openOTModal(){return _lazyCall("ot","openOTModal",arguments);}
function renderUsersView(){return _lazyRender("users","renderUsersView",arguments);}
function renderGraphsPage(){return _lazyRender("dash","renderGraphsPage",arguments);}
function renderDashboard(){return _lazyRender("dash","renderDashboard",arguments);}
if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",_bootWhenReady)}else{_bootWhenReady()}
